quests[56474] = { id = 56474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hivekiller Stinger", description = "Wasps are a bee's natural enemy, and none are more deadly than this highly specialized killer. It will terrorize the hive no longer, thanks to you.\n\nThe Hivemother will be interested in this item.", completion = "<The Hivemother buzzes animatedly at the sight of the stinger.>\n\nBzzzz!", objectives = "Take the Hivekiller Stinger to the Honeyback Hivemother for a reward.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56475] = { id = 56475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiral Yeti Horn", description = "All manner of creatures are attracted to the sweet smell of fresh honey, but relatively few are willing to withstand the painful and often deadly stings of the largest of bees. This yeti, however, has been a persistent thorn in the hive's side, until now.\n\nThe Hivemother will be interested in this item.", completion = "<The Hivemother buzzes animatedly at the sight of the horn.>\n\nBzzz! Bzzzz!", objectives = "Take the Spiral Yeti Horn to the Honeyback Hivemother for a reward.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56489] = { id = 56489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restless Dead", description = "Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there.\n\nWe have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.", completion = "Dead things in Stratholme isn't really a surprise anymore, but there's some new evil lurking within that we haven't seen before. \n\nOnly the most courageous and strong willed should enter.", objectives = "Find Sean Wilkers outside of the service entrance of Stratholme in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56490] = { id = 56490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restless Dead", description = "Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there.\n\nWe have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.", completion = "Dead things in Stratholme isn't really a surprise anymore, but there's some new evil lurking within that we haven't seen before. \n\nOnly the most courageous and strong willed should enter.", objectives = "Find Sean Wilkers outside of the service entrance of Stratholme in Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56491] = { id = 56491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiny Terrors of Stratholme", description = "Scourge activity inside of Stratholme has increased dramatically in the recent days. The air is thick with the stink of necromancy, and there are screams and shrieks coming from within these walls that will send chills down your spine for weeks to come.\n\nI haven't ventured in there yet myself, but there is definitely some new evil stirring from within. I have the keys to this entrance, and can bring you in there to see for yourself.\n\nLet me know when you are ready.", progress = "I can open these gates and bring us in, but it will be up to you to get out safely.", completion = "They did what to Blackmane!? Who are these people? Infusing a beast with strange necromancy powers certainly sounds like an escalation of events compared to what they have done previously. What can they possibly be doing with all of this stuff they are taking? It sounds like a showdown is imminent.", objectives = "Defeat Blackmane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56492] = { id = 56492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battle Challenge: Stratholme", description = "The evil presence has returned to Stratholme yet again. That's the problem with necromancy and scourge, they keep reanimating themselves and coming right back!\n\nI can bring us in there again, but I suspect all of those evil forces have returned. Are you sure you want to go back in there? That place gives me the creeps. If you really want to head back in there, I will let you back in.", progress = "I can open this service entrance, but it is up to you to safely get out of Stratholme.", completion = "They did what to Blackmane!? Who are these people? Infusing a beast with strange necromancy powers certainly sounds like an escalation of events compared to what they have done previously. What can they possibly be doing with all of this stuff they are taking? It sounds like a showdown is imminent.", objectives = "Defeat Blackmane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56493] = { id = 56493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Direct Approach", description = "Maokka has such a gentle heart. He is so good with the little ones, always playing games and telling stories.\n\nWe do however really dislike these Venture Co. individuals, so I suggest a more direct approach.\n\nTry killing them all.", completion = "You've sent them a message they won't forget.", objectives = "Eliminate 12 Venture Co. employees", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56494] = { id = 56494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eve of Battle", description = "{name}. The time has come.\n\nWe may have defeated Azshara, but we still have to deal with Sylvanas. Though our position is not ideal, we have mobilized our available forces and stand ready to finish this war.\n\nKing Wrynn wanted me to brief you on the situation before we join him. There have been some... interesting developments.", completion = "Thank you for responding with haste.", objectives = "Speak with Mathias Shaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56495] = { id = 56495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Move Against Us", description = "The Dark Lady requests your presence in Orgrimmar, {name}. \n\nIt seems the rats have finally come out of hiding. Which will make it all the easier to exterminate them.\n\nDo not delay. We have waited for this moment long enough.", progress = "The pathetic fools.", completion = "These traitors will be dealt with. No more leniency. No more weakness.", objectives = "Meet with Sylvanas in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56496] = { id = 56496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eve of Battle", description = "{name}, we must speak of the Horde... and the warchief.\n\nThe war has proven costly, and the battle against Azshara drained what little resources we had left. The Horde is divided once more and the Alliance fares little better than we do. \n\nSylvanas is now in a position to destroy everyone she considers an enemy. That means us, as well.\n\nI had hoped that my old friend would see reason, but now...\n\nHigh Overlord Saurfang is rallying those of us who remain--including some unlikely allies.", completion = "We have much to do, {name}. The Banshee moves swiftly.", objectives = "Speak with Lor'themar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56499] = { id = 56499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Battlefields", description = "We cannot afford to let up on any front, continue to press the war.", completion = "If we keep up the pressure there is no way the Horde will succeed.", objectives = "Win a PVP Island Expedition, Normal Battleground and Epic Battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56500] = { id = 56500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Battlefields", description = "We cannot afford to let up on any front, continue to press the war.", completion = "If we keep up the pressure there is no way the Alliance will succeed.", objectives = "Win a PVP Island Expedition, Normal Battleground and Epic Battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56501] = { id = 56501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking The Air Out", description = "<This box of rockets could just be used to take out the Venture Co. Balloons. That would really motivate Venture Co. to go somewhere else.>", completion = "You are a generous one. You did far more than I asked.", objectives = "Eliminate 5 Venture Co. Transports", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56504] = { id = 56504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrathion's Journal", progress = "Awaiting information interface.", completion = "Information from journal pages committed to memory. Formulating fortification schematics for Chamber of Heart.\n\nAll data recorded and catalogued. Physical transcription no longer required.", objectives = "Deliver Wrathion's incomplete journal to MOTHER.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56508] = { id = 56508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste Not", description = "<There's a variety of parts around this area that might be useful to Rustbolt. You should collect them before Venture Co takes them.>", progress = "Grab what things you can!", completion = "These parts will make someone a nice upgrade!", objectives = "Collect 20 Useful Bits and Pieces", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56515] = { id = 56515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vinyl: Gnomeregan Forever", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Gnomeregan Forever.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", completion = "<The vinyl slides neatly into the gramophone's vinyl carousel. The titleboard updates automatically.>", objectives = "Install the vinyl into the Rustbolt Gramophone.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56516] = { id = 56516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vinyl: Mimiron's Brainstorm", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Mimiron's Brainstorm.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", completion = "<The vinyl slides neatly into the gramophone's vinyl carousel. The titleboard updates automatically.>", objectives = "Install the vinyl into the Rustbolt Gramophone.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
