quests[56519] = { id = 56519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vinyl: Triumph of Gnomeregan", description = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Triumph of Gnomeregan.\"\n\nYou should be able to install this vinyl into the gramophone back in Rustbolt.>", completion = "<The vinyl slides neatly into the gramophone's vinyl carousel. The titleboard updates automatically.>", objectives = "Install the vinyl into the Rustbolt Gramophone.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56523] = { id = 56523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Chickens are Not for Eating!", description = "If you've spent any time with that arrogant nitwit, Overspark, you know why I'm here.\n\nTo silence his boasting and finally prove that my inventions are better!\n\nI've released countless mechanical chickens across this island to analyze the technology here, adopt it, and evolve their own circuitry. One of them will become my ultimate battle chicken!\n\nBut those idiot troggs think my chickens are edible and keep bashing them.\n\nProtect them, so my techno-evolutionary experiment can run its course.", progress = "Imagine being so dumb that you try to eat a mechanical chicken...", completion = "Superlative intervention, {name}!\n\nNow, we sit back and let the robots evolve themselves through natural selection... with no negative side effects whatsoever.", objectives = "Collect 20 Mechanical Giblets and repair the OOX-Bomber/MG.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56532] = { id = 56532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuke 'Em Norbit", description = "These motospiders continue to multiply unchecked. If we don't slow them down they'll overrun Rustbolt soon.\n\nI've modified Norbit here with adequate firepower to take the spiders head on!\n\nWould you pilot Norbit and destroy the Reinforced Sparkweave Eggs?", progress = "Norbit needs a skilled pilot!", completion = "Mission accomplished!", objectives = "Eliminate the 5 Reinforced Sparkweave Eggs", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56533] = { id = 56533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldvein Rumors", description = "Gather intelligence to assist SI:7 in identifying the location of the Fluctuating Worldvein.", progress = "Have you gathered enough intelligence?", completion = "This is exactly the intelligence Mathias Shaw wanted me to watch out for, I will pass it over to him immediately. I am sure he will have a Mission waiting for you.", objectives = "Collect 3 Worldvein Intelligence Reports.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56534] = { id = 56534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldvein Rumors", description = "Gather more intelligence to assist your followers in tracking down the location of the Fluctuating Worldvein.", progress = "Have you gathered enough intelligence?", completion = "Nathanos Blightcaller was looking for just this type of intelligence. I will send a runner immediately to the flagship. I am sure he will have a follow up mission for you when you arrive.", objectives = "Collect 3 Worldvein Intelligence Reports.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56536] = { id = 56536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Never Easy", description = "The last I heard, Mogu'shan Vaults was still abandoned. \n\nWe shouldn't have too tough of a time reachin' the engine, since we've already defeated the mogu guardians in that place.\n\nWell, what are ye waitin' for? Let's get that engine turned on!", progress = "It's never easy, is it?", completion = "That amber barrier looks nigh impassable.\n\nIt looks like we've hit a dead end...", objectives = "Meet Magni Bronzebeard outside Mogu'shan Vaults in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56537] = { id = 56537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysterious Sigil", description = "<The slain mogu clutches a sigil in his hand -- a symbol of the mysterious clan he belongs to.\n\nPerhaps if you could track down his clan, they may know more about the mantid's invasion of Mogu'shan Vaults and how they can be overcome.\n\nLorewalker Cho is well known as font of lore for Pandaria. He may be able to track down the origins of the mogu's sigil.>", completion = "So Mogu'shan Vaults has been taken by the mantid? A strange turn, indeed, though hardly surprising. \n\nSeeking the help of the mogu to reclaim it though, that is unexpected. Last I heard, they weren't precisely on speaking terms.", objectives = "Bring the Mysterious Mogu Sigil to Lorewalker Cho at the Seat of Knowledge in Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56538] = { id = 56538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clans of the Mogu", description = "You say a mogu asked for your help? This is quite uncharacteristic. \n\nI'd be happy to help you uncover the origins of this sigil. To be honest, the prospect of a mogu clan that isn't openly hostile interests me greatly. Just think of the possibilities!\n\nLet's get down to business. We'll need to consult the volumes on the various mogu clans in the vale to narrow it down.", progress = "Why are you talking to me? The knowledge you seek is in the tomes.", completion = "If the mogu are once again following Ra-den it could mean an end to their days of war.\n\nThis is very exciting!", objectives = "Help Lorewalker Cho discover the origin of the Mysterious Mogu Sigil at the Seat of Knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56539] = { id = 56539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Rajani", description = "Now that we have an idea of who we're looking for, the next question is, where can we find them?\n\nWith the constant infighting of the mogu, it is likely that each clan would keep tabs on the whereabouts of their competitors. If we can find such information, it may just lead us to the Rajani.\n\nSeek out the champions of the mogu. They would be the most likely to carry reports on their enemies' whereabouts.", progress = "Have you found a scouting report?", completion = "Excellent. Not only might this lead us to the Rajani, but it will prove valuable to the Golden Lotus's defense efforts.\n\nThis is valuable information, indeed!", objectives = "Collect a Mogu Scouting Report from mogu in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56540] = { id = 56540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Tenacity", description = "If the Highkeeper is so convinced that we don't stand a chance against our enemies, perhaps a show of force would sway him.\n\nI am not sure how you would manage, but if you could bring proof of a victory against those who threaten the Vale, it may convince him that action should be taken.", progress = "What is it this time?", completion = "So, you managed to defeat one of the Vale's would-be conquerors? A notable feat, but Azeroth's enemies are innumerable.\n\nThe Burning Legion, the Old Gods, the Void... sooner or later the scales will tip against this world.\n\n...but I have been mistaken before.", objectives = "Obtain a Conqueror's Trophy from the commander of an Assault in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56541] = { id = 56541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Engine of Nalak'sha", description = "Your kind have proved me wrong in the past, so I will give you a chance to do so again.\n\nThe titan structure which houses the Engine of Nalak'sha spans the entirety of Pandaria. There are more ways to reach it than just the Mogu'shan Vaults.\n\nThere are many such routes, but the closest would be through Mogu'shan Palace. The chambers beneath the palace are interconnected with the vaults. \n\nSeek your fate there, champion.", progress = "Your courage is impressive. I only hope it is not wasted.", completion = "You have done a great thing for the Rajani today, champion.\n\nI hope the Engine of Nalak'sha provided the power you seek.", objectives = "Follow the secret passage within Mogu'shan Palace and re-activate the Engine of Nalak'sha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56542] = { id = 56542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restored Hope", description = "Your persistence fills me with hope for this world. \n\nLet us return to your \"Chamber of Heart.\" As the caretaker of the Forge of Origination, I believe I can help your efforts to restore it.\n\nSpeak to me when you are ready, and I will bring us there.", completion = "Not only have we managed tae restore power tae the Forge of Origination, but we even brought back the Titan keeper that originally installed it!\n\nBut believe it or not, that's not the end o' the good news!", objectives = "Speak with Ra-den to return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56550] = { id = 56550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corpse Cleanup", description = "Our friends continue to fall as these terrible insects pour of their nests and attack our camps.\n\nIt's a terrible job to ask of anyone, but we have to dispose of the corpses as quickly as possible.\n\nWe can't allow our dead to be used as fertilizer for growing their disgusting eggs.", progress = "We need to complete this task quickly and without delay.", completion = "I hope this will help keep the growth of their numbers at bay.", objectives = "Burn 8 Egg-bearing corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56552] = { id = 56552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off-the-Books Brawlin'", description = "Gazlowe hired you for protection too? I guess it's true that he only hires the best, eh? Ha!\n\nPay's great, but the rules are dung: no fightin' in town, no exceptions. Bah!\n\n<Usha takes a big gulp of her drink.>\n\nThat tiny tender prince won't give us his tech unless he thinks we're good little angels... Ha!\n\nBut Gazlowe didn't say nothin' about fightin' outside of town.\n\nI got my own squad on the outskirts, ready to brawl with Grumbol's guzzlers if they show their bearded faces.\n\nYou want in?", completion = "Ha ha ha! Look at Grumbol's stupid face!\n\nHe can't believe it! Ha ha ha! Pathetic!", objectives = "Brawl with Grumbol Grimhammer's forces on Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56557] = { id = 56557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Side Action", description = "There are only two things more fun than fighting, and the first is talking trash!\n\n<Usha shouts an insult at Grumbol Grimhammer.>\n\nThat boar-beard runt over there's been a thorn in my backside since Alterac... Can't seem to shake him.\n\nWe got a bet going about who's the best fighter on the island.\n\nYou want to help me win this wager?", completion = "Ha! Looks like I owe you another drink.", objectives = "Slay 5 Alliance players in Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56558] = { id = 56558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off-the-Books Brawlin'", description = "*buuuurrp* Arrrright, listen 'ere. We got ourselves a bit o' a predicament.\n\nBesides this dump's ale tastin' like oil, that pigheaded Usha here been sayin' some unfortunate stuff about our troops.\n\nUnfortunate FOR HER, 'cuz now *uuuuurp* gonna needya ta rough up any Horde swine ya end up runnin' into out there.\n\nLoosely speakin' we ain't supposed to be brawlin' out 'ere, so this ain't a formal order or nothin'...", completion = "Couldn't be more proud of ya me lad! 'Ere's a little somethin' fer yer trouble.", objectives = "Brawl with Usha Eyegouge's forces on Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56559] = { id = 56559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Side Action", completion = "I knew ye wouldn't be lettin' me down!", objectives = "Slay 5 Horde players in Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56560] = { id = 56560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Discovery", description = "<This crystal shines with a mesmerizing light that you find difficult to avert your gaze from.\n\nPerhaps the Unshackled would be able to tell you more about it.>", completion = "I've seen these crystals in a couple of places, often with a weird looking slime nearby. There has to be some sort of link but I've yet to discover it. \n\nAt any rate the only use of these crystals I've found is to get tiny creatures to follow me around for a while.\n\nSorry, that doesn't help you much but you can have your crystal back. Let me know if you figure anything else out.", objectives = "Bring the Enchanting Crystal to Narv in Newhome.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56561] = { id = 56561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Discovery", description = "<This crystal shines with a mesmerizing light that you find difficult to avert your gaze from.\n\nPerhaps the Ankoan would be able to tell you more about it.>", completion = "I've seen these crystals in a couple of places, often with a strange slime nearby. Clearly there is a link between the two but I have yet to discover it. \n\nAt any rate, the only use of these crystals I have found is to hypnotize tiny creatures for a while.\n\nSorry, that does not help you much but you can have your crystal back. Let me know if you figure anything else out.", objectives = "Bring the Enchanting Crystal to Instructor Okanu in Mezzamere.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56562] = { id = 56562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Problem with Shrinkage", description = "<Having skinned countless creatures, you can't help but notice how much usable leather is lost when the skin is dried and tanned. The Ankoan seem to have mastered using the material, perhaps Instructor Ulooaka could share some of his insights.>", completion = "Apologies. We are so used to working with these materials, I forgot to explain how to prevent that. These beasts are usually underwater all the time, and the air dries them unevenly. When you skin the beast, roll the skin as you harvest it. This will rehydrate it enough to prevent waste.", objectives = "Ask Instructor Ulooaka about the shriveled leather hide.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56563] = { id = 56563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Problem with Shrinkage", description = "<Having skinned countless creatures, you can't help but notice how much usable leather is lost when the skin is dried and tanned. The Unshackled seem to have a solid understanding of using the material, perhaps Rolm could share some of his insights.>", completion = "Ah, yeah, sorry about that. We are so used to working with these materials, I forgot to explain how to prevent that. See, these beasts are usually underwater all the time, and the air dries them unevenly. When you skin the beast, roll the skin as you harvest it. That'll rehydrate it enough to prevent waste.", objectives = "Ask Rolm about the shriveled leather hide.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56565] = { id = 56565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hanging by a Thread", description = "<As you peel the hide from the creature's body, you notice numerous scales break off the skin, tearing holes that render portions of the hide useless. The Ankoan seem to have mastered using the material, perhaps Instructor Ulooaka could share some of his insights.>", completion = "I have seen this many times. The scales of these beasts are not just part of the skin, but connected by tough muscle and sinew. This allows the creature to move through the crushing depths easier. When you are ready to remove the hide, do it in two passes. The first to cut these sinuous fibers, the second to flay it. You will find more of the hide will be usable.", objectives = "Ask Instructor Ulooaka about the deteriorating cragscales.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56566] = { id = 56566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hanging by a Thread", description = "<As you peel the hide from the creature's body, you notice numerous scales break off the skin, tearing holes that render portions of the hide useless. The Unshackled seem to have mastered using the material, perhaps Rolm could share some of his insights.>", completion = "I've seen THIS before. See, the scales of these beasts are not just part of the skin, but are connected with muscle and sinew. This allows the creature to move through the crushing depths easier. When you are ready to remove the hide, do it in two passes. The first to free the scales, the second to actually skin it. That way more of the hide will be usable.", objectives = "Ask Rolm about the deteriorating cragscales.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56570] = { id = 56570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Greater Flask of the Currents", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, friend. We needed these flasks badly." }
quests[56572] = { id = 56572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toys Like Us", description = "I must share the wonders of this place with all of Azeroth in a way that will entertain young and old alike. I will use the technology here to create a new line of toys unlike anything seen before!\n\nMy Quasi-Faceted scanner can help construct perfect replicas of things here on the island. \n\nI just need a helpful individual such as yourself to scan a few things around this area.", completion = "The first batch of toys is all ready to go!", objectives = "Quasi-Facet scan creatures in Mechagon", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56573] = { id = 56573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Certified Pre-Owned", description = "First, let me say that you will ALWAYS be our favorite test subject.\n\nBut our experiments require far more sacrifice than a single test subject can offer. And, from time to time, some of those test subjects require new limbs.\n\nMy dear brother and I have a nascent concept for expanding the average lifespan of mechanical appendages. But we've run out of components to experiment on.\n\nSalvage some appendages from the heap outside town so we can continue our experiments.", progress = "Don't worry about any malfunctioning or missing parts. Gill will help us repair whatever you find.", completion = "Wondrous! This should last us...\n\n<Pristy counts the appendages and scribbles in her notebook.>\n\n...at least 3 hours. Wow, we're really churning through these appendages!", objectives = "Collect 15 Salvaged Mechagnome Appendages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56574] = { id = 56574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reflections in Amber", description = "<A viscous dark ooze drips from this large chunk of amber. Attempting to wipe it off is futile, as the ooze is seemingly created by the amber itself.\n\nAs you hold it, unintelligible whispers fill the back of your mind.\n\nThe Shado-Pan will surely want to examine it.>", completion = "What is it you have there, {name}?", objectives = "Bring the Ooze-Covered Amber to the Shado-Pan at the Serpent's Spine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56575] = { id = 56575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Into Kor'vess", description = "You found this on a member of the swarm? It seeps with corruption... and with power. We could be faced with a serious threat if the rest of the mantid's amber is similarly corrupted.\n\nFar to the west in the Dread Wastes lies Kor'vess, a large kypari tree that provides the swarm with most of its amber. From there, we can determine just how much of their stores have been infused with the energy of the Old Gods.\n\nI will meet you closer to the tree.", completion = "The mantid appear to be corrupting the entire tree. It is worse than I thought.", objectives = "Investigate Kor'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56576] = { id = 56576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aqir Extermination", description = "There are too many of these things flyin' around for us to make a clean getaway. \n\nWe're liable to get swarmed the second we start up them plane engines!\n\nThese bugs are going straight back into the ground... one way or another. May as well expedite the process, know what I mean?", completion = "That should help keep the runway clear for a bit!", objectives = "Kill 10 Aqir Impalers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56577] = { id = 56577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crippling the Hive", description = "The mantid here are working feverishly to harvest amber from the tree.\n\nPerhaps killing a pawful of them will slow their efforts.", completion = "While it is not a permanent solution, this should buy us some time.", objectives = "Kill 12 Kor'thik mantid in Kor'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56578] = { id = 56578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotten at the Roots", description = "Underneath Kypari Kor is a large chamber where the mantid tend to the tree. That must be where the source of the corruption lies.\n\nWe need to get into that chamber and stop them. N'Zoth must not be allowed to empower the swarm.", completion = "Faceless ones? The kypari trees are sacred to the mantid... but I suppose their devotion to the Old Gods is greater.", objectives = "Stop the source of the corruption within the Morrowchamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56580] = { id = 56580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amber Secrets", description = "The Morrowchamber houses a small section of the Zara'thik, mantid under immediate directive of the new empress. Some of them may have been given pieces of amber like the one you found.\n\nThe Shado-Pan would be interested in any extra pieces we can acquire.", progress = "We always feared this day would come...", completion = "More of this corrupted amber. I need to bring this back to the garrison.", objectives = "Collect 8 pieces of Corrupted Amber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56617] = { id = 56617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Unified Swarm", description = "It seemed as though the mantid had been producing the corrupted amber for some time before our... intervention. It stands to reason that they are keeping a stockpile of it somewhere.\n\nThe Shado-Pan's scouts have been reporting an increased presence of the swarm's warriors in Klaxxi'vess. I would wager that they are guarding the corrupted amber.\n\nMeet me there. If we have a chance to destroy that amber, then we need to take it.", completion = "If the entire swarm were empowered by that corrupted amber, N'Zoth would have an unstoppable army under his command.", objectives = "Infiltrate Klaxxi'vess.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56621] = { id = 56621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Real Ultimate Power", description = "When I say that power is life, I'm not speaking figuratively, my dear test subject.\n\nProperly harnessed, power can create life itself--or at least a close enough facsimile for our purposes.\n\nThere is a massive reserve of discarded technology lurking deep in the mucky depths of the Outflow. As usual, Mechagon's trash is our treasure.\n\nI've finally perfected my device that will animate the sludge to bring that technology up to the surface for you.\n\nAll you have to do is pop 'em and grab the tech!", progress = "Please thoroughly document any adverse side effects you experience while using the Spark-7143.", completion = "Glorious recovery!\n\nAnd you say that the Spark-7143 did NOT cause an extreme burning sensation in your gut?\n\n<Flip makes a quick note and smiles.>\n\nWondrous indeed!", objectives = "Collect 15 discarded technologies from techno-animated sludge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56622] = { id = 56622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Dominance", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", objectives = "Defeat the Alliance at all event locations in Ashran and kill Grand Marshal Tremblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56623] = { id = 56623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Dominance", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", objectives = "Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56640] = { id = 56640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortunate Souls", description = "You and I survived the attack and have thus far evaded capture by the enemy.\n\nNot all were as fortunate.\n\nThere are many of our allies now under the control of the naga. We must free them before they are killed or suffer an even worse fate.", progress = "We are outnumbered, but we are not outclassed.", completion = "Our army was devastated, but we will rebuild.", objectives = "Rescue 7 captive soldiers in Spears of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56641] = { id = 56641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disruption of Power", description = "The naga are tapping into some latent power, infusing the energy into some manner of device.\n\nI do not know what purpose they have for this power, but it is surely in our interest to destroy the objects before they can be used against us.", progress = "Can you feel the magic in this place?", completion = "At times it is satisfying to break another's toys.", objectives = "Destroy 5 Ley Line Accumulators in Spears of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56642] = { id = 56642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Tides", description = "A tidemistress leads some nefarious ritual above a pool.\n\nDo not look in the pool when we approach it, or you will be rewarded with a view of our drowned allies.\n\nWe must put a stop to this ritual. The tidemistress is key.", progress = "We must not underestimate this tidemistress.", completion = "The ritual ceased as soon as we killed the tidemistress.", objectives = "Slay Tidemistress Ethendriss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56643] = { id = 56643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Deep", description = "By now, King Greymane and Lady Proudmoore should be in the cave at which we are to meet.\n\nLet's not keep them waiting.", completion = "I already tire of this place.", objectives = "Meet Jaina and Genn in the cave within Spears of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56644] = { id = 56644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up Against It", description = "We must move quickly if we are to find safety for our people.\n\nThis cave is barely defensible, and much of our army is in an even more precarious position.\n\nLet's search deeper.", completion = "We have been watching you. Your people seem quite capable.", objectives = "Move deeper into Nazjatar with Jaina and Genn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56645] = { id = 56645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Swarm", description = "We need to know what we're up against. Before we return to the Serpent's Spine, we should take the opportunity to scout the swarm.\n\nI will fly us over the Heart of Fear. We should be able to survey Empress Shek'zara's forces from above. Then we can determine the extent to which N'Zoth has bolstered their ranks with his own.", completion = "A close call. Thank you, {name}.", objectives = "Fly with Taoshi on the Shado-Pan Kite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56647] = { id = 56647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantid Threat", description = "The mantid have been corrupting their kypari trees to imbue their amber with power from N'Zoth. The swarm is enough of a menace on its own. N'Zoth could transform them into something even more dire.\n\nThe Shado-Pan need to hear about this. I suggest you bring this information to your other allies as well.", completion = "That the mantid would give their own kypari trees over to corruption speaks volumes of their loyalty to N'Zoth.\n\nThank you for bringing this to my attention.", objectives = "Return to Stormspeaker Qian at the Silent Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56648] = { id = 56648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Nazjatar", description = "Our mission in Nazjatar is being compromised by the Horde incursion. \n\nGet into Nazjatar and take out as many as you can.", completion = "Good work, {class}.", objectives = "Slay Horde within Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56649] = { id = 56649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Mechagon", description = "Our mission in Mechagon is being compromised by the Horde incursion. \n\nGet into Mechagon and take out as many as you can.", completion = "Good work, {class}.", objectives = "Slay Horde within Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56650] = { id = 56650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Mechagon", description = "Our objectives in Mechagon are being interrupted by the influx of Alliance scum.\n\nClear as many of them out of the area that you find, then report back.", completion = "Good work, {class}.", objectives = "Slay Alliance within Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56714] = { id = 56714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contained Alemental", description = "<As the brew is returned to its natural, dormant form, a strange keg appears.\n\nPerhaps Brewmaster Tao knows more about such a strange occurrence.>", completion = "Everything has a spirit to it. From the clouds in the sky to the worms in the ground, life is woven through the entire world.\n\nBrew is no different. Created with such love, such care... it only requires a spark to spring to life in front of our very eyes.", objectives = "Talk to Brewmaster Tao in the Brewfest grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56715] = { id = 56715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen Totem", description = "<The hozen have been successfully chased away, and Brewfest saved once again.\n\nThe question asks itself, though: How did hozen get to Durotar? Perhaps somebody in the Brewfest grounds has experience with them.>", completion = "<Zenda spits on the hozen totem.>\n\nDo not be fooled by deir appearance. Dese hozen are ruthless. Some chased my brother out of his own bar in Zuldazar and took it over as deir own!\n\nI have seen dese winged ones, and dey are unwelcome wherever dey go.", objectives = "Talk to Zenda in the Brewfest grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56716] = { id = 56716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direbrew Cog", description = "<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines.\n\nYou know they have attacked Brewfest before. Perhaps one of the goblins would be interested in hearing of your victory.>", completion = "So Direbrew still ain't giving up, is he?\n\nWell, thanks for taking care of his lackeys again. Thanks to you, I still have business! Take these tokens as a reward... but be sure to come back and spend them later!", objectives = "Talk to Blix Fixwidget in the Brewfest grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56719] = { id = 56719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Ain't Mine", description = "Your arrival is timely, {name}. Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. \n\nWe are cut off from our vanguard and I fear that they will be destroyed if we cannot reinforce them quickly. Our forces are few in number. We cannot afford to leave them stranded for long.\n\nTinkmaster Overspark and Gazlowe believe they have a solution. Hurry and aid them however you can.", progress = "Thank the Light you were able to open the pass.", completion = "We may have rejoined the vanguard, but Sylvanas's forces have been harrying our front line.", objectives = "Clear the pass of boulders, mines, and other obstructions between Razor Hill and Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56739] = { id = 56739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Worship", description = "I was once like them, stuck in a loop and waiting for Azshara to come and save me. Our spirits are locked to this place.\n\nThere are naga in the other parts of these ruins. They have these magical orbs... I think they are using us to fuel their arcane experiments. They draw power from our spirits and our worship of Azshara. This keeps us weakened and unable to break free.\n\nDestroy the orbs. Breaking the connection will allow us to gain strength and move on.", progress = "Have you found them all?", completion = "Without the draw of energy, I believe that the other spirits will eventually be able to break out of their loop. They will be able to move on.", objectives = "Destroy 3 Arcane Energy Transmuters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56740] = { id = 56740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "S.P.A.R.E. Crates", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", completion = "Look at all those spare parts you've got in those bags! You're starting to look like a real junkyard tinkerer.\n\nLet me give you a tip, though. Only amateurs carry 'em around all helter skelter like that.\n\nReal experts keep 'em organized efficiently, so we can carry more.\n\nHere, I'll show you how." }
quests[56741] = { id = 56741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spear of Destiny", description = "The Javelins are some of the most powerful magical creations of Suramar, before the Sundering. This is just what we need to bring down the wards on the protector and the Tidestone.\n\nWe must hurry back to Mezzamere, Lady Proudmoore needs to know of our success.\n\nThis will change the entire course of our campaign here in Nazjatar, {name}.", completion = "This is an amazing find, {name}. With this, we can assault the guardian of the Tidestone, and secure it.", objectives = "Return to Jaina Proudmoore in Mezzamere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56746] = { id = 56746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Direct Line", description = "I'm sure you agree that Pascal-K1N6 is the greatest invention you've ever seen!\n\nIf you're not convinced yet, try to push him to his limits. I don't mind!\n\nBring him more resources and blueprints -- he'll craft anything you need!", completion = "Madam Goya wishes to convey her appreciation for your continued support of her operations.\n\nShe's asked me to entrust you with the blueprints for our encrypted communication network, so you can always stay in touch.\n\nDo not share this with anyone, {name}.\n\nWe'll be watching." }
quests[56747] = { id = 56747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Akunda's Bite", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, {name}. Your contribution has been logged in our records for posterity to appreciate!", objectives = "Bring 20 Storm Silver Ore to Gila Crosswire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56748] = { id = 56748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Chowdown", description = "Mok-rah, {class}! I hope you came with an empty stomach!\n\nBack on Draenor, we often held eating contests at our festivals as a form of celebration. When we were put in charge of Brewfest, we could think of nothing better to add to the event!\n\nTake a seat and show us what you can eat. If you want more details before jumping in, just ask!", progress = "Eat a sausage, drink some brew, then eat some more!", completion = "Well eaten! Every time you win, you'll receive a token as a reward. Once you collect five, come back to me and I can award you with a beautiful trophy!", objectives = "Participate in the Brewfest Chowdown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56749] = { id = 56749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Akunda's Bite", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you.", objectives = "Bring 20 Storm Silver Ore to Skaggit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
