quests[56756] = { id = 56756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Punkin, the Action Figure", description = "Heya, {name}.\n\n<Grizzek leans in close and whispers.>\n\nI'm workin' on a surprise for Saffy. Hopin' you can help me out.\n\nI overheard her beggin' Jepetto Joybuzz to make her into one of his fancy new action figures.\n\nThat ol' jerk told her no. Can you believe it? My Punkin!\n\nWell, we don't need him. I reverse engineered a few of his toys and found out what makes them tick.\n\nI got a blueprint ready to go. We can make Saffy's action figure ourselves and surprise her with it!", progress = "You've got the spark of discovery in your eyes!", completion = "<Sapphronetta's eyes light up as you hand her the action figure of herself.>", objectives = "Craft the Sapphronetta Flivvers Action Figure at Pascal-K1N6.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
