quests[56764] = { id = 56764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Chowdown", description = "Welcome, {class}! I hope you came with an empty stomach!\n\nWhat's better, or more Brewfest, than sausage and brew? The Brewfest Chowdown is our new celebration of the things that make this festival great.\n\nTake a seat and show us what you can eat. If you want more details before jumping in, just ask!", progress = "Eat a sausage, drink some brew, then eat some more!", completion = "Well eaten! Every time you win, you'll receive a token as a reward. Once you collect five, come back to me and I can award you with a beautiful trophy!", objectives = "Participate in the Brewfest Chowdown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56765] = { id = 56765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Lane Snapper", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you.", objectives = "Bring 20 Storm Silver Ore to Skaggit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
