quests[56771] = { id = 56771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time-Lost Warriors", description = "According to the scouting report ye found, the Rajani are holed up in the Silent Sanctuary, overlooking Mistfall Village. \n\nThey are described in the report as seclusive and dangerous, so we'd had best take caution when approaching them.\n\nI'll meet ye there.", progress = "What is it, outsider?", completion = "It is of no use. The great Highkeeper is convinced of our fate.\n\nIt will take more than words to move him.", objectives = "Meet with the Rajani at the Silent Sanctuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
