quests[56774] = { id = 56774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Greater Flask of the Undertow", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, friend. We needed these flasks badly." }
quests[56775] = { id = 56775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warming Up", description = "Prepare yourself, {name}. We're nearing the island where the previous expedition was lost.\n\nWarm up on these combat dummies. We need everyone ready for whatever we find on that island.", progress = "Don't be shy. Just walk up to the target dummies, select them, and use your main attack.", completion = "Good, looks like you've kept up your {class} training during our voyage.\n\nI'm concerned about the sudden turn in weather. Spar with Private Cole while I speak with the ship's crew.\n\nCole's report will determine where we'll place you on our initial expedition team.", objectives = "Warm up by fighting a Combat Dummy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56777] = { id = 56777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift From The Clan", description = "Speaker Utia has requested that I direct you back to Mezzamere when you have a chance, {name}.\n\nOur clan has prepared a gift for you to show our appreciation for the courage and valor you have shown in battle against the naga.\n\nI am sure that you will find the gift of supplies to be a valuable addition to your arsenal as you continue your campaign against Azshara.", completion = "You have brought honor to our clan, {name}. Please accept these additional supplies along with our thanks.", objectives = "Meet with Speaker Utia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56778] = { id = 56778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Glint in the Darkness", description = "There are many treasures hidden throughout Nazjatar.\n\nRecently, I spotted an object glinting from within a cave not far from here. It appeared to be some sort of lockbox.\n\nI suggest we head back and investigate. There may be valuable items inside that will help us in our battle against the naga.", objectives = "Loot the Lambent Lockbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56779] = { id = 56779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Valorous Reward", description = "Your deeds on the battlefield have brought honor upon your Alliance, {class}.\n\nSpeaker Utia has requested your presence in Mezzamere to accept a reward on behalf of our clan.\n\nYou should return to Mezzamere at your soonest convenience.\n\nIt is an honor to fight at your side.", completion = "Please accept this gift of supplies. May it serve you well.", objectives = "Meet with Speaker Utia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56780] = { id = 56780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden, But Dangerous", description = "The naga have hidden many useful treasures throughout Nazjatar.\n\nI have heard tell that there is a treasure hoard not far from here. It will be dangerous, but it may be worth investigating.\n\nThere may be untold valuables inside the cache that could aid us in our fight against the naga.", objectives = "Loot the Mystic Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56781] = { id = 56781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure In The Deep", description = "There are many treasures to be found throughout the naga stronghold of Nazjatar.\n\nSome time ago, I noticed a mysterious looking chest. The area was heavily fortified with naga troops, so whatever it contains must be valuable.\n\nWe should go back and investigate the chest. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "Loot the Mysterious Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56782] = { id = 56782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Speaker's Gift", description = "Speaker Utia has requested your presence in Mezzamere, {name}.\n\nI believe that the Speaker has prepared a collection of items to aid you in your journey.\n\nYou should return to Mezzamere at your soonest convenience and accept the Speaker's gift.", completion = "Please accept this gift on behalf of our clan. May it serve you well.", objectives = "Meet with Speaker Utia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56783] = { id = 56783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lambent Lockbox", description = "There are many treasures to find throughout these ancient ruins.\n\nSometime ago, I noticed a strange looking chest in a cave not far from here.\n\nThere may be valuable items inside that can help us in our fight against Queen Azshara.\n\nWe should go back and investigate the chest.", objectives = "Loot the Lambent Lockbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56784] = { id = 56784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helpful Provisions", description = "Speaker Utia is awaiting your return to Mezzamere.\n\nThe Speaker has bundled together some helpful provisions to aid you in your journey.\n\nPlease accept this gift with the thanks of our clan.", completion = "Please accept this gift of supplies. May you be well-equipped in your battles against the naga.", objectives = "Meet with Speaker Utia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56785] = { id = 56785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mystic Chest", description = "We have uncovered many rare treasures while exploring Nazjatar. I believe that I have found yet another cache of valuable artifacts to retrieve.\n\nSome time ago, I noticed a strangely glowing object in the distance. I believe that it may have been a treasure chest.\n\nWe should go and investigate the object. If it is a treasure chest, its contents may prove valuable in our quest to defeat the naga!", objectives = "Loot the Mystic Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56786] = { id = 56786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Treasure", description = "The naga have stashed away the spoils of their wars throughout Nazjatar.\n\nEarlier while we were adventuring, I noticed a mysterious looking cache. The chest is located deep within naga territory, so I imagine that whatever is inside is most likely extremely valuable.\n\nWe should retrieve the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "Loot the Mysterious Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56787] = { id = 56787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Additional Supplies", description = "Speaker Utia has asked me to send you back to Mezzamere when you have a moment, {name}.\n\nThe Speaker has some additional supplies that might aid you in your fight against the naga.\n\nPlease return to Mezzamere at your soonest convenience and accept the Speaker's gift with the thanks of our entire clan.", completion = "May these additional supplies aid you in your journey, {name}.", objectives = "Meet with Speaker Utia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56788] = { id = 56788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaimed Treasure", description = "The naga have filled Nazjatar with the ill-gotten spoils of war. We should reclaim whatever we come across in our effort to put an end to their tyranny once and for all.\n\nI noticed a strange looking chest in a cave nearby. It appeared to be of naga make.\n\nWe should claim the contents of the cache. There may be valuable items inside that will help us in our battle against the naga.", objectives = "Loot the Lambent Lockbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56789] = { id = 56789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift of Supplies", description = "Speaker Utia has asked that I send you back to Mezzamere at your soonest convenience.\n\nThe Speaker has gathered together a gift of supplies to further aid you in your fight against the naga.\n\nYou should return to Mezzamere at your soonest convenience. Please accept this gift with the thanks of our clan.", completion = "Please accept this gift of supplies. May it serve you well.", objectives = "Meet with Speaker Utia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56790] = { id = 56790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure To Find", description = "The naga have stashed away treasures all over Nazjatar.\n\nNot long ago, I noticed an ornately crafted treasure chest hidden in plain view. The area is heavily fortified, but such minor inconveniences have not stopped us yet.\n\nWe should head back there and liberate the contents of the cache.", objectives = "Loot the Mystic Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56791] = { id = 56791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Treasure", description = "We have located many treasure hoards while exploring Nazjatar. I believe that I have found yet another cache for us to liberate.\n\nSome time ago, I noticed a mysterious looking chest. It is held in an extremely dangerous area, so whatever it contains must be valuable.\n\nWe should embark on a mission to liberate the contents of the cache. Whatever is inside is better used in our hands than the hands of the enemy.", objectives = "Loot the Mysterious Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56793] = { id = 56793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Mech-Dowel's \"Big Mech\"", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, friend. We needed this food badly." }
