quests[56827] = { id = 56827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Enchant Weapon - Naga Hide", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, friend. We needed these enchantments badly." }
quests[56829] = { id = 56829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bottom Feeders", description = "Oh this is bad. This is really bad.\n\nEvery time one of the lads makes it down here they don't come back. Things that come down here... they sort of stay down here one way or another.\n\nLet's make a deal. You're a Maw Walker. You go find Cudgelface and the Chamberlain while I get this here carriage back in service and then we all get out of here before somethin' tries to eat us and THEN go to work on us.", completion = "Ah good. No one got ate.\n\nCarriage is ready to go when you are.", objectives = "Find Cudgelface and the Lord Chamberlain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56830] = { id = 56830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summons from the Deep" }
quests[56833] = { id = 56833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaders of the Horde", description = "Saurfang has shown his true colors and now enlists the aid of the Alliance. \n\nMeet with those who have remained loyal to the Horde. They are to ready themselves for the battle against our enemies.\n\nAnd as for Eitrigg... bring him to Nathanos. A quick death is too lenient a punishment for his treachery.\n\nGo, {name}. Let us end this.", progress = "There is no honor in this battle, {name}.", completion = "So be it. Our choices have been made.", objectives = "Order the Horde leaders in Orgrimmar to prepare for battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56839] = { id = 56839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killclaw the Terrible", description = "<You see a crude sign made by the ogres. It contains a warning.>\n\nBIG bear! Bad!\n\nBig bear guard big ogre treasure!\n\nKill after ritual! Get treasure, make more power!", completion = "<You find a cache of treasure, just like the ogres' sign mentioned!>", objectives = "Defeat Killclaw the Terrible.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56842] = { id = 56842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunar Preservation", description = "My staff has served me well for many years. It has stood by my side, been through many trials... and as I grow older I find myself leaning on it more and more.\n\nIts flowers bloom every Lunar Festival, basking in the Elune's might. They bring me so much joy, I wish for them to stay all year long. I know a way... but my bones are too old to make the trip.\n\nPerhaps you would take the journey for me? Empower my staff in the light of the moon at the moonwells around the world. Then my flowers can stay.", progress = "Flowers flourish under Elune's light. She was always known to cherish them.", completion = "You've done it! I can feel Elune's power within. Now I can enjoy the company of my flowers for the rest of my days.\n\nPerhaps I can do the same for you. If you have flowers you wish to preserve, bring them to me. I may be able to help.", objectives = "Perform the Rite of the Moon at the moonwells scattered around the world. You can find them in Ashenvale, Felwood, Feralas, Moonglade, Stonetalon Mountains, Duskwood, and Mount Hyjal.\n\nIf you let the Blessing of the Moon expire, you will have to start over.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56877] = { id = 56877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Extra Sticky Situation" }
quests[56889] = { id = 56889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wounded Wastewanderers", description = "Ahh, my friend, have you returned to render additional aid?\n\nAs you can see, we are still locked in battle with these creatures, with no end to their numbers in sight.\n\nThis is a war of attrition and we find ourselves at a clear disadvantage as injuries continue to mount.\n\nPlease, assist any of our wounded that you find within the ruins.", progress = "Do you require additional bandages?", completion = "Your help is greatly appreciated, my friend.", objectives = "Heal 6 Wastewander Laborers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56903] = { id = 56903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of Courage", description = "I see you are a fan of pink flowers. It is a shame those that make up your crown will one day come to perish.\n\nPerhaps I can help with that.\n\nThough those are ordinary blossoms, I know similar flowers that bloom only during Lunar Festival. If you retrieve them for me, I can imbue them with Elune's power so that you may enjoy them throughout the year.", progress = "Not all flowers are equal. Those that bloom during Lunar Festival have a special bond with Elune.", completion = "Such beautiful flowers! I can feel Elune's might within them.\n\nThis crown shall bring you great courage.", objectives = "Gather blooms from Eversong Woods, the Hinterlands, and Mulgore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56904] = { id = 56904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of Prosperity", description = "Your crown is so colorful! Such beautiful pinks and yellows and blues... if only it could last.\n\nAlthough those particular flowers cannot, I know some that can!\n\nSimilar flowers to those bloom every Lunar Festival. They hold a special connection to Elune that I can empower, thanks to you. Retrieve them for me, and we can fashion a crown that you can enjoy year round!", progress = "Elune has a soft spot for flowers. Those that bloom during Lunar Festival are quite special.", completion = "Such a multitude of colors! These flowers will bring happiness to all who see them.\n\nThis crown shall bring you great prosperity.", objectives = "Gather blooms from Un'goro Crater, Stranglethorn Vale, and Northern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56905] = { id = 56905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of Dark Blossoms", description = "Such somber flowers... but they hold a beauty of their own, don't you think? If only they could last.\n\nAllow me to lend my aid.\n\nEvery Lunar Festival, similar flowers to yours bloom around the world. They hold a special connection to Elune... one that I can empower. If you bring them to me, I can preserve them so you may enjoy them long after an ordinary flower would die.", progress = "The flowers that bloom during Lunar Festival have special properties. I believe it is Elune's light watching over them.", completion = "Ah, what calming flowers. I sense a solemn peace emanating from them.\n\nThis crown shall support you with a silent grace.", objectives = "Gather blooms from Duskwood, Silverpine Forest, and Desolace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56906] = { id = 56906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crown of Good Fortune", description = "Those flowers remind me of Elune herself! I wear similar ones year round, to remind me of her watchful grace.\n\nPerhaps you would like to as well?\n\nYour crown is made of ordinary blossoms that will one day wilt and die. It is an unfortunate fate for such delicate beauties, but my crown is made of similar flowers that I made to last year round! If you bring me specific flowers that bloom only during Lunar Festival, I can bless them so that you too can enjoy your crown all year long.", progress = "Between you and me, I believe these flowers are Elune's favorite. They mirror her lunar radiance so splendidly!", completion = "Ah, flowers that match my own. I can feel Elune's presence within them.\n\nThis crown shall bring you great fortune in life.", objectives = "Gather blooms from Winterspring, Dun Morogh, and Hillsbrad Foothills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56907] = { id = 56907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Bottle: Nukular Red", description = "<Kram Kelada could make use of this item.>", completion = "Good color choice!", objectives = "Deliver the item to Kram Kelada.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56908] = { id = 56908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Bottle: Goblin Green", description = "<Kram Kelada could make use of this item.>", completion = "Good color choice!", objectives = "Deliver the item to Kram Kelada.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56909] = { id = 56909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Bottle: Electric Blue", description = "<Kram Kelada could make use of this item.>", completion = "Good color choice!", objectives = "Deliver the item to Kram Kelada.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56914] = { id = 56914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angry Residents", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56942] = { id = 56942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On The Road Again", description = "Right lads! All aboard!", completion = "We are not getting the carriage through that.", objectives = "Ride the Carriage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56955] = { id = 56955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebels on the Road", description = "This is unacceptable. The stoneborn rebels have ambushed a convoy intended for the Tithelord. He is the local Harvester who rules this ward. \n\nWe need to get through this mess. The bridge on the far side of this conflict leads to Darkhaven. The Master typically keeps some of his own Stone Legion forces there. \n\nCarve us a way through, Maw Walker. Destroy any who would delay us. We must not keep Sire Denathrius waiting.", completion = "Your talents in combat show promise. Perhaps with a few more centuries and a little humility we might make something of you.", objectives = "Slay 5 Stoneborn Rebels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56969] = { id = 56969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Reefwalker Bark", progress = "Yes? What is it?", completion = "We use reefwalker bark for many things, from buildings to armor. \n\nThis one must have come from one of the elder ones, it's huge! We can make many things from it.\n\nI will distribute this bounty to the camp, thank you!" }
quests[56970] = { id = 56970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reefwalker Bark", progress = "Yes? What is it?", completion = "We use reefwalker bark for many things, from buildings to armor. \n\nI will distribute this bounty to the camp, thank you!" }
quests[56971] = { id = 56971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eel Filet", progress = "Yes? What is it?", completion = "My favorite! How did you know?\n\nI will cook it up for the camp, everyone is going to enjoy this." }
quests[56972] = { id = 56972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fathom Ray Wing", progress = "Yes? What is it?", completion = "That is a nice, juicy wing you have there. \n\nI will cook this up, there's plenty to go around." }
quests[56973] = { id = 56973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giant Crab Leg", progress = "Yes? What is it?", completion = "Wow, that is a large one. Looks delicious!\n\nI'll make some soup for tonight, the group is going to love it." }
quests[56978] = { id = 56978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Darkhaven", description = "Across this bridge is the hamlet of Darkhaven. It is fortified by those loyal to Sire Denathrius. These pitiful rebels would not dare approach it.\n\nHowever, getting to it may prove challenging. Here, I shall carry the anima, you make sure no one throws us back into the Endmire.", completion = "It may not look like it, but this rebellion is on its last leg. Those who stand against the Master are fools who will know a new form of pain and suffering.", objectives = "Escort Lord Chamberlain to Darkhaven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56979] = { id = 56979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Siege", description = "In the chaos of the rockslides, Sylvanas dispatched her saboteurs to sneak past our sentries and plant bombs on our siege weaponry. \n\nSeveral of them have already been lost. We cannot afford to lose more.", completion = "Our people are tired and our resources are dwindling. We need every weapon and soldier at our disposal if we are to take the city.", objectives = "Remove 8 Suspicious Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56980] = { id = 56980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Already Among Us", description = "While some of the Horde have joined forces with us, many within Orgrimmar remain loyal to Sylvanas. Her saboteurs have infiltrated our ranks and are posing as our technicians. Her assassins are lurking in the shadows.\n\nStop any loyalists you encounter, before they can cause any harm.", completion = "I wish this bloodshed wasn't necessary.", objectives = "Slay 10 Suspicious Technicians or Loyalist Assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56981] = { id = 56981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Deployment", description = "Saurfang maintains that the key to taking Orgrimmar is to exploit its multiple points of entry. He led the city's defenses for years, and knows its vulnerabilities better than anyone. We are spread thin as it is, but I trust his judgment in this matter.\n\nWe must also fortify Thunder Bluff in case Sylvanas plans to assault it while our forces are committed here.\n\nDeliver these deployment orders to our officers. We will assail all of Orgrimmar's gates at once while also defending Thunder Bluff.", completion = "Our forces are in place. All that is left is to begin the battle.", objectives = "Deliver Anduin's deployment orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56982] = { id = 56982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Gates of Orgrimmar", completion = "Saurfang... he gave his life so our soldiers wouldn't lose theirs.\n\nNone of us anticipated he would challenge Sylvanas directly. But perhaps she did.\n\n<Jaina shakes her head.> \n\nIt does us no good to debate whether this was part of her plan or if she merely took advantage of an opportunity. We must be on our guard against her schemes.\n\nSaurfang won his final battle. I do not know what will become of the Horde, but I have hope that they will find a new path to follow.", objectives = "Begin the battle at the gates of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[56993] = { id = 56993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of Victory", description = "Saurfang... how could this have happened....\n\n<Jaina takes a moment to compose herself.>\n\nThe Alliance has known High Overlord Saurfang as both a sworn enemy and an invaluable ally.\n\nAnduin will want to honor his memory. Recall our forces and inform them of what has happened. Genn's soldiers were dispatched to the western gate. You should be able to find him there.", progress = "He died a warrior's death, as he always wanted. I suppose there is some comfort in that.", completion = "Many have lost their lives to this war. Let us hope Saurfang is the last.", objectives = "Recall the Alliance forces and inform them of what has transpired.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57001] = { id = 57001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valley of Honor" }
quests[57003] = { id = 57003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Create Your Own Strength", description = "For something that has been sitting on the ocean floor, there is still power to be found in this item.\n\nTake your piece of Benthic armor to Voidbinder Zorlan. He has been eyeing it with great curiosity.\n\nGo ahead and humor the ethereal and let him have a look.\n\nMaybe he has something to offer.", completion = "Ancient elven magic and the ocean infusing things with her own power...\n\nI would like to say I'm surprised, but I'm really not.\n\nIt's a good thing you brought those shiny fellows to help sort it all out.", objectives = "Upgrade a piece of Benthic armor through Voidbinder Zorlan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57004] = { id = 57004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Create Your Own Strength", description = "That Benthic armor you carry has been lost beneath the tides for too long.\n\nThere is still power within it.\n\nVoidbinder Sturzah may be able to provide insight.\n\nTake your find to our intrepid ethereal friend, and see what he can do with it.", progress = "Were you successful?", completion = "There is bond formed between the ocean and what comes to rest beneath its waves.\n\nThe glowing man will be able to use the Prismatic Manapearls to improve the Benthic items.\n\nThis will prove most beneficial.", objectives = "Upgrade a piece of Benthic armor through Voidbinder Sturzah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57005] = { id = 57005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming a Friend", description = "Some of our bravest kelfin have volunteered to join you on your adventures, should you ever need a friend.\n\nYou will find they each have their own special interests and they will mark your map with different opportunities every day.\n\nUse the conch when you're ready, choose who you would like to join you, and explore Nazjatar!\n\nChoose wisely! You may only select one friend per day.", completion = "It is good to have you here, {name}.\n\nThat was masterfully handled. You have made the Unshackled excited and hopeful. \n\nI really couldn't ask for more.", objectives = "Use the Calling Conch, choose an ally, and complete 3 ally quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57006] = { id = 57006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Ally", description = "Some of our bravest ankoan have volunteered to join you on your expedition.\n\nYou will find each have their own special interests and they will mark your map with different opportunities every day.\n\nUse the Deepflame Campfire when you are ready. Choose a noble ally to join you, and explore what remains of Nazjatar.\n\nChoose wisely! You may only select one friend per day.", completion = "My brethren reported that you were quite skilled in the field, {name}.\n\nWe are honored to have you here.", objectives = "Use the Deepflame Campfire, choose an ally, and complete 3 ally quests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57007] = { id = 57007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invitation of the Master", description = "The great Sire Denathrius, Master of Revendreth, and King of the venthyr, has asked me, his loyal Chamberlain, to escort you safely to his personal gardens. This is an honor never before bestowed upon a living mortal. \n\nYou should feel honored.\n\nCome, join me in the carriage and we shall ride to the castle in style.", completion = "Oh good, still not dead yet?\n\nYou see where the Lord Chamberlain or Cudgelface landed?", objectives = "Ride the Darkhaven Carriage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57008] = { id = 57008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: The Warring Clans", description = "The opportunistic mogu clans seek to take the Vale while its defenders are recovering from N'Zoth's attack. \n\nThey are both cowardly and foolish.\n\nShow them the error of their ways.", progress = "Yes?", completion = "These pretenders will learn that they must either join the Rajani or be ground to dust.\n\nYou have done well to show them that.", objectives = "Drive back the Mogu Assault in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57009] = { id = 57009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fame Waits for Gnome One", description = "Tinkmaster Overspark requests your assistance on an important research expedition. \n\nWorking with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", completion = "Now we can begin the expedition.", objectives = "Meet with Tinkmaster Overspark in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57010] = { id = 57010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harnessing the Power", description = "Heart Forge online.\n\nInitiate final attunement sequence.\n\nAwaiting input from champion unit {name}.", progress = "Standing by.", completion = "Well, well! Looks like the Heart o' Azeroth has got new capabilities, just like MOTHER said!\n\nBe on the lookout fer more o' those essences. They've got tae be all over Azeroth.", objectives = "Use the Petrified Ebony Scale atop the Heart Forge to infuse its power into the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57022] = { id = 57022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: Amathet Advance" }
quests[57023] = { id = 57023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weighted Mogu Artifact" }
quests[57024] = { id = 57024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumors of Mechagon", description = "I knew I should've taken that gig with the Greasemonkeys...\n\nGazlowe's crew always get paid, and no dumb risks. I heard they got somethin' big comin' up too...", completion = "Well, ain't this a pleasant surprise.", objectives = "Meet Gazlowe outside the Great Seal in Dazar'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57025] = { id = 57025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plea to Revendreth", description = "Revendreth is quite possibly the most... efficient... realm at extracting anima. Perhaps they can lend aid where others cannot. \n\nKnow that while souls sometimes return from Revendreth, they are never the same when they do. It is a dark realm, where those the Arbiter deems worthy of a chance of redemption are sent.\n\nTheir path, however, is not an easy one.\n\nKah-Sher will assist you in opening the gateway to Revendreth. Meet him in the Ring of Transference.", completion = "Sorry for the state of things. Usually a venthyr would be here to greet you. Been a while since we seen anyone come through that gate.\n\nAll good, though, as I know the welcome speech better than a good mornin' whipping.", objectives = "Journey to Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57026] = { id = 57026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sinstone", description = "Well, you ain't like the others. Usually you're supposed to be dead before you come here. Ah well. A sin is a sin and a stone is a stone, as it goes.\n\nLet's get you sorted out with your sinstone. This way, if you please.", completion = "Hopefully these wretched creatures did not bore you with their inane babble.", objectives = "Take the tour.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57037] = { id = 57037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Once Sweet Sound", description = "The bells! That sound!\n\nTheir song has been twisted! If their dire toll continues, we will all succumb.\n\n<Eridia presses her hammer into your hands.>\n\nFind the great vespers within the temple and strike them with my hammer. May the mallet's tonal purity restore their true voices!\n\nI will listen for their clarion call and meet you near the bridge. Go swiftly!", progress = "Such a bitter sound!", completion = "I can hear their song once more. It is a boon on my mind, but the loudest voice remains. We must silence it before it destroys all that we hold dear.", objectives = "Cleanse the Vesper of Purity and the Vesper of Harmony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57039] = { id = 57039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valley of Spirits" }
quests[57045] = { id = 57045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Delivery", description = "I'm glad you're finally here, {name}. I've got an important delivery to make and you're the goblin I trust most.\n\nYeah, yeah. I know that's not sayin' much, but it's hard to find good help these days!\n\nThis package is for Hobart Grapplehammer. He's got a workshop in Crapopolis and I need you to deliver it to him. He's been working on somethin' big lately!\n\nDeliver the package and for the love of money... DON'T DROP IT!\n\nYou have no idea how long it took me to locate this thing!", progress = "Gallywix sure has some nerve threatening me in my own laboratory!\n\nHe thinks he can just do whatever he wants to whoever he wants...", completion = "Sassy Hardwrench asked you to deliver this package?\n\nAh! These must be the parts I ordered last month. I can finally begin the final round of testing on my latest invention!", objectives = "Deliver the package to Hobart Grapplehammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57047] = { id = 57047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Simple Experiment", description = "Now that you've delivered the necessary parts, I can begin testing my latest prototype!\n\nI call it the X-52 Personnel Armor! It will be nearly indestructible!\n\nGallywix has always coveted my inventions and now that he knows about the X-52 I'm sure he'll be up to no good. I've gotta complete the prototype before Gallywix comes up with a way to steal it out from under me!\n\nI could really use an extra set of hands with the experiments.\n\nCan I count on you, {name}?", progress = "We need to complete the X-52 Personnel Armor before Gallywix finds a way to steal the prototype!", completion = "Good work, {name}! The experiments were mostly successful! However, it does look like we'll need to find a new lab assistant for the explosives testing...", objectives = "Assist Hobart Grapplehammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57048] = { id = 57048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shopping For Parts", description = "I'm going to need some additional components in order to complete the next phase of testing.\n\nRight now, what we need most are thermoplugs and thermoplug adaptors! I'll explain what they're for later...\n\nCrank Greasefuse runs a shop near the entrance of the town. Go speak with Crank and get him to fork over the necessary parts.\n\nI don't care what they cost, just tell him to bill me later! I can't be bothered to negotiate right now. I need to prepare the modifications to the X-52 Personnel Armor!", completion = "Thermoplugs, eh? Yeah I got some more here... but they ain't cheap!", objectives = "Speak with Crank Greasefuse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57049] = { id = 57049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of Souls" }
quests[57051] = { id = 57051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debt Collection!", description = "You need thermoplugs? Well, you came to the right place, kid.\n\nBut I ain't giving 'em to you on credit. There's way too many shlubs who haven't paid me back the money they owe. I'm in over my head here, if I don't get paid fast, I'll be out of business in no time.\n\n<Crank Greasefuse thinks for a moment.>\n\nLook, I tell you what... If you can muscle those no-good goons into paying me my money, I'll give you the thermoplugs as payment.\n\nYou won't find a better deal than that!", progress = "You got my money?", completion = "<Crank Greasefuse takes a moment to count the money.>\n\nIt's all here! Good work, kid! The thermoplugs are all yours. Send my regards to Grapplehammer and tell him to name one of his inventions after me!", objectives = "Collect 8 Unpaid Debts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57052] = { id = 57052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got What You Need", description = "A deal's a deal, {name}. Here's the thermoplugs you ordered!\n\nBe sure to let that ol' grouch Grapplehammer know that I won't be giving out anymore handouts. If he needs more thermoplugs he'd better be ready to pay up.\n\nAnyway, it was a pleasure doing business with you...\n\nNow get lost!", completion = "Yes! These are exactly what I need to finish the landmines for the upcoming experiment...\n\nOh, I didn't mention landmines?\n\nI thought I did... oh well! I'll explain everything later! It'll be fine!", objectives = "Deliver the package to Hobart Grapplehammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57053] = { id = 57053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blunt Force Testing", description = "Now that we have the thermoplugs we're ready for our next test of the prototype X-52 Personnel Armor!\n\nUnfortunately, my lab assistants have either quit or expired. What a pity! But their loss is your gain, {name}... now YOU get to wear the X-52 Personnel Armor!\n\nHow exciting!\n\nThe next test will be conducted by my new mechanized lab assistant. Head over to the main workshop and press the big red button to begin.\n\nDon't worry, I'll be giving you directions over the X-52's built in intercom!", progress = "Everything depends on this experiment!", completion = "<Hobart Grapplehammer examines you closely.>\n\nThis is fantastic! You're currently suffering a moderate amount of internal bleeding, but the prototype X-52 Personnel Armor performed just as I predicted under extreme levels of repeated blunt force.\n\nThe X-52 doesn't have a scratch on it!", objectives = "Complete Hobart Grapplehammer's experiment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57058] = { id = 57058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fun With Landmines", description = "The prototype X-52 Personnel Armor is ready for the final test! \n\nHow are you with loud noises and sudden bursts of concussive energy, {name}?\n\nFor the final test, we're going to strap you into the X-52 Personnel Armor and have you traverse a minefield!\n\nI have placed a refreshing coconut beverage in the center of the minefield. Consider the drink a fitting reward for reaching the oasis and surviving the inevitable explosions in the process!", progress = "Ballistic testing... IS MY FAVORITE!", completion = "These goons are demolishing my workshop! We've gotta do something fast!", objectives = "Retrieve the refreshing coconut beverage from the minefield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57059] = { id = 57059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Rumble!", description = "This is bad, {name}! Real bad!\n\nGallywix and his goons are destroying my workshop, but he's got another thing coming if he thinks I'm gonna hand over the X-52 Personnel Armor!\n\nYou've gotta get down there and clear out his goon squad before this place--AND ALL MY INVENTIONS--go up in flames!", progress = "Hurry, {name}! Gallywix and his goons are destroying my worskshop!", completion = "Good work getting rid of Gallywix, {name}, but I've got a bad feeling about this. We need to find a buyer for the X-52 before Gallywix comes back.\n\nWho knows what he'll try next...", objectives = "Defeat 8 Hired Scoundrels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57067] = { id = 57067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu at the Gates", description = "The time has come. The other mogu clans have set their sights on the Vale of Eternal Blossoms.\n\nThey will not conquer it.\n\nSome of your kind have already gone to the gate to scout out the size of their force. If you think yourself worthy for such a mission, meet them there.", completion = "The mogu have not massed in numbers like this since... well I cannot remember!\n\nWe must be careful. They have overtaken the entire plains.", objectives = "Meet Chen and Li Li Stormstout at the Gate of the August Celestials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57068] = { id = 57068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kite Surveillance", description = "We heard for ourselves that there were mogu attacking, but I had no idea it would be this many!\n\nThere must be a way to stop them before they completely overrun the Vale. Quickly, let us fly over and scout out their numbers.\n\nWe just so happen to have a kite that can carry three people. Usually it's more, but I had a big lunch.", completion = "Oh no, we went down hard. Uncle Chen can't get up! And there are mogu everywhere!\n\nIt's okay. It's fine. We'll think of something.", objectives = "Ride Chen's Kite to scout the Mogu armies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57069] = { id = 57069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Off the Heads", description = "Okay. We're stuck in the middle of three mogu armies, and Uncle Chen is too hurt to move yet.\n\nIt's not hopeless though. We have the chance to take out the leaders of these armies. Maybe that will slow them down or distract them long enough for us to get back to the gate!\n\nSee if you can get out there and take down the biggest, baddest mogu you can find. Those will be the commanders.", completion = "Good job. The mogu are not as strong without their leaders.", objectives = "Slay mogu commanders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57070] = { id = 57070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Massacre", description = "I think this is what my friends would call a \"target rich environment.\" As a nicer way of saying \"we're surrounded and probably doomed.\"\n\nYou know what this means. We have to kill as many of these mogu as possible! It doesn't matter how you do it, just take them out!", completion = "That's a lot of mogu down. Hopefully that will thin their ranks enough for us to get out of here.", objectives = "Slay mogu in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57071] = { id = 57071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Brew Left Behind", description = "My head is... hurting. There can be only one solution.\n\nWe flew over an abandoned brew caravan. You must go find it, and save that brew! That should help bring me back to full strength.\n\nPlus, it would do wonders for the morale of those fighting in the Vale, if we can recover it.", completion = "<These must be the brew barrels Chen spotted when flying over.\n\nThey are too heavy to carry on your own.>", objectives = "Locate the abandoned brew barrels in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57072] = { id = 57072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yak of All Trades", description = "<The brew barrels are too heavy and numerous to carry alone.\n\nPerhaps you can find something, or someone, to help you.>", completion = "What is this? You found a yak?\n\nAnd what's more, you found brew!", objectives = "Find something to help you carry the brew back to Chen in Mogujia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57074] = { id = 57074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Backs to the Gate", description = "It is most fortuitous that you found this brew, and a yak to carry it on!\n\nBut we cannot remain here. Li Li has healed me up enough to travel. We can ride the yak back to the gate and hope that the mogu do not notice our passing.\n\nLet me know when you are ready to leave.", completion = "We got through! Now, what are we going to do about all those mogu?", objectives = "Ride Mobi with Chen and Li Li to the Gate of August Celestials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57075] = { id = 57075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquid Courage", description = "We have to do something about all these mogu. At least to thin their ranks before they invade the Vale!\n\nAs much as Uncle Chen loves his brew, I think we can put it to better use. Let's hop onto that yak and give the mogu something to fear!", progress = "Something must be done about all these mogu, or we will lose the Vale.", completion = "All that lovely brew... gone.\n\nBut let us look on the bright side. There are fewer mogu to contend with now. It is time for us to report back.", objectives = "Mount Mobi and defeat the mogu armies with the power of brew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57076] = { id = 57076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Mistfall", description = "We have done all we can here. We know how much the mogu are a clear threat.\n\nThe forge is in great danger of falling into their hands if we lose our hold on the Vale.\n\nLet us return to Mistfall and report to the Rajani. They will want to know what we are up against.", completion = "So the other clans seek to invade the Vale with their armies?\n\nWe will show them what true might looks like.", objectives = "Return to Stormspeaker Qian in the Silent Sanctuary in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57077] = { id = 57077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buyers Wanted!", description = "The X-52 Personnel Armor is finally complete and Gallywix has been sent packing with his tail between his legs!\n\nI've got you to thank for this, {name}!\n\nBut we're still not done... the best part is yet to come. We're going to hold an auction and sell the X-52 Personnel Armor to the highest bidder!\n\nSassy Hardwrench should have a list of interested buyers ready to go. Head over to Hardwrench Hideaway and let her know we're ready for the auction!", completion = "So the invention is complete, huh? Good work, kiddo! We'll be rolling in moolah in no time!", objectives = "Speak with Sassy Hardwrench in Stranglethorn Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57078] = { id = 57078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The VIP List", description = "While you've been assisting Grapplehammer with his newest invention, I've been hard at work finding potential buyers!\n\nThis is going to be a private auction, so we're only inviting the best and the brightest, the cream of the crop, the creme de la creme... got it?\n\nI've narrowed the potential buyers down to an 'A' list of only the wealthiest, classiest, most connected goblins around... minus Gallywix, of course!\n\nHead out and deliver these invitations while I finish up preparations for the auction!", progress = "This will be an 'A' list event. Only Kezan's finest will be in attendance!", completion = "You delivered the invitations? Good! We're going to need all the help we can get... I've got some bad news for you!\n\nDid I say bad news? I meant REALLY bad news!", objectives = "Deliver the invitations to Grapplehammer's private auction.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57079] = { id = 57079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beat The Crapopolis Outta Him!", description = "Boy am I glad to see you! We've got a bad situation on our hands...\n\nWhile you were away delivering the invitations, Gallywix and his goons took over Crapopolis! They're holding Hobart Grapplehammer hostage until he hands over the X-52 Personnel Armor!\n\nYou have to stop Gallywix before it's too late!", completion = "The X-52 Personnel Armor is ruined beyond repair... but at least Crapopolis is saved and Gallywix finally got what he deserves!", objectives = "Complete the Crapopolis scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57080] = { id = 57080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting Reward", description = "Although the X-52 Personnel Armor's power-core was destroyed during the battle with Gallywix, the invention was a success!\n\nI doubt anyone will be interested in purchasing the rights to the X-52 without a working power-core, so why don't you hang onto the armor instead? It is quite stylish after all!\n\nNow that Crapopolis is saved and Gallywix is conveniently trapped inside of his own mechanical pummeler, I think I'm going to renegotiate that \"contract\" of his.\n\nHe is a \"captive audience\" after all!You will learn:", sourceObjective = "Thank you for everything you've done for me, {name}! You've saved Crapopolis and put that no good, double-crossing Gallywix in his place!\n\nTake the X-52 Personnel Armor along with my thanks. It looks good on you!", sourceObjectiveStatus = "unverified-source-field" }
quests[57085] = { id = 57085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowered War Wagon" }
quests[57086] = { id = 57086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Mad Mage", description = "<This rather large jewel has an inscription etched on its base:\n\nProperty of Mardivas. If found please return to my laboratory. \n\nPerhaps this laboratory can still be found somewhere?>", progress = "<The chest appears to be simply constructed, but the locking mechanism hums with arcane energy.>", completion = "<The ancient lock clicks open, revealing the contents within.>", objectives = "Investigate Mardivas's Laboratory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57087] = { id = 57087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baruk Obliterator" }
quests[57088] = { id = 57088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Ain't Mine", description = "Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. Our forces are now cut off from each other.\n\nWe need to reinforce our front line or the Banshee will pick us off at her leisure. We have come too far to be slain by a thousand cuts.\n\nGazlowe and one of the Alliance's gnomes believe they have an answer. You'd best ensure that their plan does not backfire.", progress = "Hmm. Maybe that goblin's gadgets have some use.", completion = "Swift action saved our soldiers' lives, but there is still more to do.", objectives = "Clear the pass of boulders, mines, and other obstructions between Razor Hill and Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57089] = { id = 57089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vil'thik Hatchery" }
quests[57090] = { id = 57090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Siege", description = "The Banshee's spies were able to sneak past our guards in the chaos of the rockslides. They've been planting bombs on our siege weaponry.\n\nGet rid of those bombs.", completion = "Well done. We cannot afford to lose any more of our weaponry to Sylvanas's treachery.", objectives = "Remove 8 Suspicious Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57091] = { id = 57091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Already Among Us", description = "Sylvanas still commands the loyalty of many within the Horde. The war she started has blinded them with rage and hatred. She exploits that to maintain her support.\n\n<Saurfang scowls.>\n\nThey do not yet see she will lead us to ruin, that her so-called victories are all hollow.\n\nSome of her agents have been spotted lurking within our ranks. Kill them. They will show us no mercy, and will have none in return.", completion = "We both have blood on our hands. Today, we will see that it has not been in vain.", objectives = "Slay 10 Suspicious Technicians or Loyalist Assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57092] = { id = 57092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Deployment", description = "For years, I guarded the gates of Orgrimmar. The city's greatest weakness has always been its multiple entrances. We should strike at all of them to seize victory.\n\nWrynn and I have drawn up orders for deployment. The mages will cover our flank. Greymane will close in from the west, and the elves will take the north. We will send Mayla to reinforce Thunder Bluff's defenses in case Sylvanas launches a counterattack.\n\nBring the orders to our commanders.", completion = "No matter what our strategy, taking Orgrimmar will be no easy task. I should know.", objectives = "Deliver Saurfang's deployment orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57093] = { id = 57093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Gates of Orgrimmar", description = "It is time.\n\nWe have done all that we can to prepare. All that remains is the battle itself.\n\nI am not one for speeches. So I will say only this.\n\nLok-tar ogar, {name}. Victory. Or death.", completion = "Saurfang... slain by dark magic... \n\nI have known Sylvanas for years, yet I have never seen her wield such power. Why reveal it to us now? What does she gain by abandoning the Horde?\n\n<Lor'themar's eye narrows.>\n\nWhatever she has planned, it would seem that she no longer requires the Horde to achieve it. We will need to be cautious, {name}. There is no telling what her next move will be.", objectives = "Begin the battle at the gates of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57094] = { id = 57094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of Victory", description = "Saurfang... I...\n\n<Lor'themar takes a moment to compose himself.>\n\n...Thrall will wish to honor Saurfang's sacrifice. And so shall the rest of us.\n\nRecall our forces. Let them know what has transpired. Tell them that the great warrior Varok Saurfang is dead and that the warchief has abandoned us.\n\nSpeak to Baine when you arrive in Thunder Bluff. You will find him on the Elder Rise. I am certain he will want to pay his respects to Saurfang as well. \n\nLet us stand as a united Horde once more.", progress = "He earned the warrior's death he always sought. There is honor in that.", completion = "Saurfang's death will not be in vain.", objectives = "Inform Baine Bloodhoof of what has transpired.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57098] = { id = 57098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grove of Terror", description = "Ah, yes. You've done me a great favor in delivering the Accuser, Maw Walker. \n\nTo celebrate, I must insist that you take part in a sacred tradition of Revendreth: The Penitent Hunt. It is a duty we undertake to strike a humbling fear into the hearts of the most... stubborn souls.\n\nFear can be a very powerful motivator for change.\n\nMeet the Fearstalker in the Grove of Terror below. There you will prepare.", completion = "Welcome to the Grove of Terror.\n\nHere you will see the beginning of the process for the anima you seek.", objectives = "Meet the Fearstalker in the Grove of Terror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57099] = { id = 57099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dreadful Roundup", description = "Welcome to The Banewood, Maw Walker.\n\nAs Huntmaster it is my duty to lead the Fearstalk. Our first order of business is to collect the souls selected for the hunt.\n\nIn the woods behind me we have souls who have been ripening for several hundred years now. Go choose the souls who will be hunted today.", objectives = "Collect 6 Condemned Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57100] = { id = 57100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding Time is Over", description = "A crucial element to a successful Fearstalk is our tool: the fangs of a terrorbeast.\n\nTheir fangs are perfect for revealing the scent of their prey once bound to a soul. There's plenty of them in the forest surrounding the ripening souls. \n\nGo and collect some from their corpses. Their population is a bit large right now anyhow.", objectives = "Kill Winged Terrorbeasts and collect 6 of their fangs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57101] = { id = 57101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zan-Tien Serpent Cage" }
quests[57102] = { id = 57102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pardon Our Dust", description = "Ah yes, the Greeter.\n\nIt seems this Mnemis unit has been deactivated. Anima has been so scarce of late, and with no new souls entering our gates... I suppose it was a prudent measure. Anima is our most precious resource, after all.\n\nThere are some centurions nearby. A portion of their Anima could serve our needs.\n\nAh! One of our most helpful stewards is here to lend her aid. She will guide you in the collection effort.\n\nReturn when you have sufficient Anima and we will power the Greeter once more.", progress = "<The centurion is unresponsive.>", completion = "<The centurion emits a soft chime.>", objectives = "Collect anima from nearby centurions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57103] = { id = 57103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrade Your Vehicle (Optional)" }
quests[57104] = { id = 57104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition GG-118 Micro-Jetpack" }
quests[57105] = { id = 57105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrade Your Jetpack (Optional)" }
quests[57106] = { id = 57106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition A.T.O.M.I.K. Mk. II" }
quests[57107] = { id = 57107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrade Your A.T.O.M.I.K. Mk. II (Optional)" }
quests[57113] = { id = 57113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Lysonia's Trail", description = "Our scouts have reported spotting Lysonia and Uther en route to the Temple of Humility.\n\nAs the de facto leader of the Forsworn, we must not allow her to stand free, twisting the minds of those around her.\n\nThe disciples of Humility have not answered our beckons. I have sent Kleia ahead to reconnoiter. Meet her outside the temple.", completion = "The entire temple is overrun with Forsworn. We must find the survivors!", objectives = "Meet Kleia outside the Temple of Humility.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57114] = { id = 57114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerial Reconnaissance", description = "The temple grounds are crawling with those loyal to the Forsworn.\n\nIf I were still an aspirant, this task would be monumental. Luckily, that is no longer the case.\n\nLet us survey the situation from the sky. We can both take stock of the challenges ahead and find any survivors we can.", completion = "Fortunate that you both found us. \n\nThere are many wounded. I have been able to keep them alive, but it has taken all of my focus. You must help us push back against the Forsworn.", objectives = "Fly with Kleia to find the survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57115] = { id = 57115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Scrolls of Humility", description = "The Forsworn are ransacking the library, looking for specific texts amongst our archives.\n\nWe cannot allow them to uncover the scrolls they are searching for. Find any set aside scrolls and return them to me for safekeeping.", progress = "The scrolls throughout these temples cover many topics, from information on different worlds, to training pillars, to ancient rituals.", completion = "It seems they are gathering information on performing one of our strongest rituals. But for what purpose?", objectives = "Collect 5 Sacred Scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57116] = { id = 57116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Succumbing to Pride", description = "The aspirants that spend the most time at this temple are those who must face their pride.\n\nI was one of them, once.\n\nDuring our surveillance, I saw Forsworn forcing these aspirants to fall to their vices then toss them aside as if they meant nothing.\n\nYou must stop the Forsworn. Free the aspirants from a terrible fate.", completion = "Thank you, {name}. These aspirants will live to improve themselves and serve Bastion.", objectives = "Free 5 Burdened Aspirants by stopping Forsworn rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57117] = { id = 57117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen to Their Vices", description = "Lysonia's forces ransack our sacred temple... they are long gone from the Archon's embrace.\n\nIt pains me to say, but you must defeat them so they can no longer abuse our people.\n\nTake Compassion with you. You will find it more than helpful, now that its power has returned.", completion = "Fighting the Forsworn, our brothers and sisters... it never gets easier.", objectives = "Defeat 15 Forsworn forces in the Terrace of Inner Grace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57118] = { id = 57118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distorted by the Maw", description = "Lysonia's forces are rerouting the anima collectors to spew Maw energy across the temple. They hamper our forces while strengthening their own.\n\nThe collectors have been tainted. Take Compassion and destroy them to halt Lysonia's boon.", completion = "Do not worry about the collectors. With the drought, they have been barely functioning for quite some time.", objectives = "Destroy 3 Anima Collectors in the Terrace of Inner Grace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57120] = { id = 57120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compassion, Blade of Humility", description = "<You find a familiar sword impaled into one of the Forsworn corpses. The Paragon of Humility must have left it behind in pursuit of Lysonia.\n\nIt seems inert, as if all its anima has been used. Perhaps you could restore it to its usual glory.>", progress = "The Paragon rarely uses his weapon. He prefers debate and reason over the use of force.", completion = "Compassion!\n\nThe Paragon chased Lysonia in such a rush, he left his sword behind. This may be key to expelling the Forsworn from the temple.\n\nTake it with you, and may it serve you well.", objectives = "Charge Compassion, Blade of Humility by killing manifestations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57121] = { id = 57121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of the Maw", description = "Lysonia flees to the Maw to enact her dark rituals. As the Maw Walker, you are the only one who can pursue her.\n\nTake Kleia and my blade. She must be stopped.", completion = "I can feel the oppression here, as if it were a real weight on my body.", objectives = "Enter the Maw with Kleia, then meet her outside Perdition Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57122] = { id = 57122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Step Too Far", description = "My initial scouting revealed things I did not believe at first.\n\nThe Mawsworn hold Forsworn captive here, transforming them against their will.\n\nThough the Forsworn stand against the Archon, they are still kyrian. It is our duty to free them.", progress = "I cannot stand idly by while my brothers and sisters are tormented.", completion = "Exiled by the Archon... failed by Lysonia...\n\nWhere can they go?", objectives = "Free 5 Captive Forsworn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57123] = { id = 57123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrian No More", description = "Mawsworn kyrian... I have not seen one since that vision when we first met.\n\nI am not intimidated. They are enemies of Bastion, of the Archon, and it is our duty to defeat them.", completion = "If my mind were ever to be twisted by the Maw... I ask that you cut me down.\n\nI cannot bear the thought.", objectives = "Kill 15 Mawsworn forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57124] = { id = 57124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her Will, Inflicted", description = "I feel myself drawn across the double bridges to the west...\n\nLysonia must be there.\n\nCome, {name}. We must confront her before she can escape again. Who knows what she plans.", completion = "It seems that... I am the fool.", objectives = "Confront Lysonia in the Altar of Domination.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57125] = { id = 57125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Reflect", description = "I knew that Devos had powerful allies. I turned a blind eye. When Lysonia took her place... I was blinded by my loyalty.\n\nI have much to reflect on.\n\nWe may not be allies, but I have one request. Please, escort me from this wretched place. I will leave you be... but do not leave me here in the Maw.", completion = "It is unfortunate to hear that Lysonia has escaped us again... The revelations of both her master and her new powers are quite concerning.", objectives = "Speak to Kleia to exit the Maw, then return to Polemarch Adrestes in Elysian Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57126] = { id = 57126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...And Following Seas", description = "My brother Derek died in the Second War, only to be raised against his will by the Banshee Queen. If not for Baine Bloodhoof's courageous act of defiance, Derek would have been turned into a weapon against my family.\n\nHe's lived in torment since his awakening. I feared he would be lost to us, but he has received help from an old friend of mine who has also been recently raised--Calia Menethil. She has guided him back from the brink of despair.\n\nI am on my way to pay them a visit. Care to join me?", completion = "Welcome. It's nice to have company.\n\nAh, Jaina has arrived.", objectives = "Visit Derek Proudmoore and Calia Menethil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[57129] = { id = 57129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valley of Wisdom" }
quests[57130] = { id = 57130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors In Our Midst", description = "There is a difference between loyalty and blind obedience. I am done following the Banshee's orders!", completion = "The warchief has long suspected that this traitor lacks the necessary resolve.\n\nYou, on the other hand... You understand.", objectives = "Deal with this traitor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
